class Solution {
  public String majorityFrequencyGroup(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) freq[c - 'a']++;
    int[] groupSize = new int[s.length() + 1];
    for (int f : freq) if (f > 0) groupSize[f]++;
    int best = 0;
    for (int k = 1; k <= s.length(); k++) {
      if (groupSize[k] >= groupSize[best]) best = k;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < 26; i++) if (freq[i] == best) sb.append((char) ('a' + i));
    return sb.toString();
  }
}
